SELECT *, AVG(shipping_fee) OVER (PARTITION BY customer_id ORDER BY amount ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS shipping_fee_avg_3_prior, LAST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY status, channel ORDER BY shipping_fee ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel, LAST_VALUE(discount, TRUE) OVER (PARTITION BY status ORDER BY order_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_discount FROM orders;
